#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
import subprocess
from pathlib import Path


def replace_once(path: str, old: str, new: str, label: str) -> None:
    target = Path(path)
    text = target.read_text()
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one match in {path}, found {count}")
    target.write_text(text.replace(old, new, 1))


replace_once(
    "tests/audit/tracked-specialist-closure.test.ts",
    'fs.writeFileSync(destination, `${JSON.stringify(aqaShapedMap(), null, 2)}\\\\n`);',
    'fs.writeFileSync(destination, `${JSON.stringify(aqaShapedMap(), null, 2)}\\n`);',
    "normalize progressive-repair fixture",
)
subprocess.run(["python", ".github/implementation/apply-locality-aware-closure.py"], check=True)

replace_once(
    "src/core/audit/specialist-completion.ts",
    'function pathSemanticTokens(paths: readonly string[], label: string): Set<string> {\n  return semanticTokens(`${label} ${paths.join(" ")}`);\n}\n',
    'function pathSemanticTokens(paths: readonly string[], label: string): Set<string> {\n  // Directory names are useful for locality scoring but are weak semantic\n  // evidence. Including them here lets a repository or package name make\n  // every sibling implementation look related to one accepted concern.\n  // Compare only the behavioral label and file stems; path affinity is\n  // evaluated independently by directoryAffinity().\n  const stems = paths.map((repositoryPath) => filenameStem(repositoryPath));\n  return semanticTokens(`${label} ${stems.join(" ")}`);\n}\n',
    "narrow semantic attachment tokens",
)

Path("scripts").mkdir(exist_ok=True)
Path("tests").mkdir(exist_ok=True)
Path("scripts/verify-implementation-diff.mjs").write_bytes(base64.b64decode(''))
Path("tests/implementation-diff-gate.test.mjs").write_bytes(base64.b64decode(''))

package_path = Path("package.json")
package = json.loads(package_path.read_text())
package["scripts"]["verify:source"] = "npm run verify:repository-clean && npm run typecheck && npm run test:all"
package["scripts"]["verify:repository-clean"] = "node scripts/verify-implementation-diff.mjs"
package_path.write_text(json.dumps(package, indent=2) + "\n")

replace_once(
    ".github/workflows/ci.yml",
    '      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7\n        with:\n          node-version: "22.19.0"\n          cache: npm\n      - run: npm ci\n      - run: npm run typecheck\n',
    '      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n        with:\n          fetch-depth: 0\n      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7\n        with:\n          node-version: "22.19.0"\n          cache: npm\n      - name: Reject staging-only implementation diffs\n        if: github.event_name == \'pull_request\'\n        run: >-\n          node scripts/verify-implementation-diff.mjs\n          "${{ github.event.pull_request.base.sha }}"\n          "${{ github.event.pull_request.head.sha }}"\n      - run: npm ci\n      - run: npm run typecheck\n',
    "install permanent implementation-diff CI gate",
)

print("corrective locality-aware implementation materialized")
